{
  "name": "@howaboua/opencode-roadmap-plugin",
  "version": "0.2.1",
  "description": "Strategic roadmap planning and multi-agent coordination for OpenCode",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "plugin",
    "roadmap",
    "planning",
    "multi-agent"
  ],
  "author": "howaboua",
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/node": "^20.0.0",
    "@typescript-eslint/eslint-plugin": "^8.48.1",
    "@typescript-eslint/parser": "^8.48.1",
    "eslint": "^9.39.1",
    "eslint-config-prettier": "^10.1.8",
    "typescript": "^5.0.0"
  },
  "dependencies": {
    "zod": "^3.22.0"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json && npm run copy-assets",
    "copy-assets": "mkdir -p dist/src/descriptions dist/src/errors && cp src/descriptions/*.txt dist/src/descriptions/ && cp src/errors/*.txt dist/src/errors/",
    "lint": "eslint . --ext .ts",
    "prepublishOnly": "npm run build"
  },
  "publishConfig": {
    "access": "public"
  },
  "opencode": {
    "type": "plugin",
    "tools": [
      "createroadmap",
      "updateroadmap",
      "readroadmap"
    ]
  }
}

import { RoadmapPlugin as impl } from "./src/index.js";
export const RoadmapPlugin = impl;
export default RoadmapPlugin;

import { createCreateRoadmapTool } from "./tools/createroadmap.js";
import { createUpdateRoadmapTool } from "./tools/updateroadmap.js";
import { createReadRoadmapTool } from "./tools/readroadmap.js";
export const RoadmapPlugin = async ({ directory }) => {
    return {
        tool: {
            createroadmap: await createCreateRoadmapTool(directory),
            updateroadmap: await createUpdateRoadmapTool(directory),
            readroadmap: await createReadRoadmapTool(directory),
        },
    };
};
export default RoadmapPlugin;
